"""Tests for the engine-side AcroForm read/fill/flatten (the CLI
parity implementation; the GUI path is renderer-side pdf-lib)."""

import re
import os

import pikepdf
import pytest
from pikepdf import Dictionary, Name

from engine.extract_text import extract_text
from engine.forms import FF_MULTISELECT, fill_form_fields, read_form_fields, reset_form_fields

FIXTURES_DIR = os.path.join(os.path.dirname(__file__), "fixtures")
# Generated by pdf-lib (the GUI's own library) — the exact input shape the
# renderer path produces/handles: text, multiline text, checkbox, /Opt-indexed
# radio group, dropdown. Cross-tool input for the engine implementation.
PDFLIB_FORM = os.path.join(FIXTURES_DIR, "form-pdflib.pdf")

# The vendored fallback fonts (Rust `get_edit_font_path` at runtime); the
# Unicode-appearance tests need them and skip when the bundle isn't provisioned.
FONTS_DIR = os.path.join(
    os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "resources", "fonts"
)
_HAS_FONTS = os.path.isfile(os.path.join(FONTS_DIR, "LiberationSans-Regular.ttf"))


def _make_raw_form(path: str) -> None:
    """A form built with raw pikepdf objects: inherited /FT via a parent
    field, a dotted name, an /Opt dropdown with [export, display] pairs, and
    an AcroForm-level /DA — the inheritance shapes the walker must handle."""
    pdf = pikepdf.new()
    page = pdf.add_blank_page(page_size=(400, 400))
    helv = pdf.make_indirect(
        Dictionary(Type=Name.Font, Subtype=Name.Type1, BaseFont=Name.Helvetica, Encoding=Name.WinAnsiEncoding)
    )

    def widget(rect):
        return pdf.make_indirect(
            Dictionary(
                Type=Name.Annot,
                Subtype=Name.Widget,
                Rect=rect,
                F=4,
                P=page.obj,
            )
        )

    # Parent "person" carries /FT /Tx that the kids inherit; kids are fields
    # with their own /T (dotted names) that are ALSO merged widgets.
    first = widget([40, 340, 200, 364])
    first["/T"] = pikepdf.String("first")
    last = widget([40, 300, 200, 324])
    last["/T"] = pikepdf.String("last")
    person = pdf.make_indirect(
        Dictionary(T=pikepdf.String("person"), FT=Name.Tx, Kids=pikepdf.Array([first, last]))
    )
    first["/Parent"] = person
    last["/Parent"] = person

    # Read-only text field.
    locked = widget([40, 260, 200, 284])
    locked["/T"] = pikepdf.String("locked")
    locked["/FT"] = Name.Tx
    locked["/Ff"] = 1

    # Dropdown with [export, display] /Opt pairs.
    combo = widget([40, 220, 200, 244])
    combo["/T"] = pikepdf.String("country")
    combo["/FT"] = Name.Ch
    combo["/Ff"] = 1 << 17
    combo["/Opt"] = pikepdf.Array(
        [
            pikepdf.Array([pikepdf.String("US"), pikepdf.String("United States")]),
            pikepdf.Array([pikepdf.String("CA"), pikepdf.String("Canada")]),
        ]
    )

    page.obj["/Annots"] = pikepdf.Array([first, last, locked, combo])
    pdf.Root["/AcroForm"] = pdf.make_indirect(
        Dictionary(
            Fields=pikepdf.Array([person, locked, combo]),
            DA=pikepdf.String("/Helv 0 Tf 0 g"),
            DR=Dictionary(Font=Dictionary(Helv=helv)),
        )
    )
    pdf.save(path)
    pdf.close()


class TestReadFormFields:
    def test_pdflib_fixture_enumeration(self):
        r = read_form_fields(PDFLIB_FORM)
        assert r["has_xfa"] is False
        by_name = {f["name"]: f for f in r["fields"]}
        assert by_name["applicant.name"]["type"] == "text"
        assert by_name["applicant.name"]["multiline"] is False
        assert by_name["notes"]["multiline"] is True
        assert by_name["agree"]["type"] == "checkbox"
        assert by_name["agree"]["value"] is False
        assert by_name["color"]["type"] == "radio"
        assert by_name["color"]["options"] == ["red", "blue"]
        assert by_name["size"]["type"] == "dropdown"
        assert by_name["size"]["options"] == ["small", "medium", "large"]

    def test_checkbox_export_value_is_the_documents_own_on_state(self, tmp_dir):
        # A check box whose /AP /N on-state is /1 stores "1" when checked. A
        # consumer that assumes "Yes" compares against a string this document
        # never uses.
        src = os.path.join(tmp_dir, "cb.pdf")
        pdf = pikepdf.new()
        page = pdf.add_blank_page(page_size=(300, 300))
        ap = Dictionary(
            N=Dictionary(
                **{"1": pdf.make_stream(b"q Q"), "Off": pdf.make_stream(b"q Q")}
            )
        )
        widget = pdf.make_indirect(
            Dictionary(
                Type=Name.Annot,
                Subtype=Name.Widget,
                Rect=[40, 200, 56, 216],
                FT=Name.Btn,
                T=pikepdf.String("optin"),
                AP=ap,
            )
        )
        page.obj["/Annots"] = pikepdf.Array([widget])
        pdf.Root["/AcroForm"] = pdf.make_indirect(Dictionary(Fields=pikepdf.Array([widget])))
        pdf.save(src)
        pdf.close()

        entry = {f["name"]: f for f in read_form_fields(src)["fields"]}["optin"]
        assert entry["type"] == "checkbox"
        assert entry["export_value"] == "1"

    def test_raw_fixture_inheritance_and_dotted_names(self, tmp_dir):
        src = os.path.join(tmp_dir, "raw.pdf")
        _make_raw_form(src)
        r = read_form_fields(src)
        by_name = {f["name"]: f for f in r["fields"]}
        # /FT inherited from the parent; names are dotted.
        assert by_name["person.first"]["type"] == "text"
        assert by_name["person.last"]["type"] == "text"
        assert by_name["locked"]["read_only"] is True
        assert by_name["country"]["options"] == ["United States", "Canada"]

    def test_no_form(self, sample_pdf):
        r = read_form_fields(sample_pdf)
        assert r["fields"] == [] and r["count"] == 0

    def test_fc3_widgets_carry_page_and_rect(self, tmp_dir):
        # Each field reports its widgets' 0-based page + normalized rect —
        # incl. the NESTED typed-terminal kids (person.first/last), which the
        # engine already enumerates and now list WITH geometry (the shape
        # the on-canvas overlay needs when the read routes through the engine).
        src = os.path.join(tmp_dir, "raw.pdf")
        _make_raw_form(src)
        by = {f["name"]: f for f in read_form_fields(src)["fields"]}
        assert by["person.first"]["widgets"] == [
            {"page": 0, "rect": [40.0, 340.0, 200.0, 364.0], "hidden": False}
        ]
        assert by["person.last"]["widgets"] == [
            {"page": 0, "rect": [40.0, 300.0, 200.0, 324.0], "hidden": False}
        ]
        assert all("widgets" in f for f in by.values())

    def test_fc3_widget_page_index_across_pages(self, tmp_dir):
        # A widget on the SECOND page reports page index 1 — resolved via the
        # page's /Annots even though the widget carries no /P.
        out = os.path.join(tmp_dir, "multi.pdf")
        pdf = pikepdf.new()
        pdf.add_blank_page(page_size=(300, 300))
        p1 = pdf.add_blank_page(page_size=(300, 300))
        w = pdf.make_indirect(
            Dictionary(
                Type=Name.Annot, Subtype=Name.Widget, Rect=[10, 20, 110, 44],
                FT=Name.Tx, T=pikepdf.String("f2"),
            )
        )
        p1.obj["/Annots"] = pikepdf.Array([w])
        pdf.Root["/AcroForm"] = Dictionary(Fields=pikepdf.Array([w]))
        pdf.save(out)
        pdf.close()
        f2 = next(f for f in read_form_fields(out)["fields"] if f["name"] == "f2")
        assert f2["widgets"] == [{"page": 1, "rect": [10.0, 20.0, 110.0, 44.0], "hidden": False}]

    def test_fc4_multiselect_optionlist(self, tmp_dir):
        # A LIST value on a multi-select list box stores /V as the export
        # ARRAY + /I as the sorted selected indices, regenerates an appearance,
        # and reads back the full selection. A single string still works.
        src = os.path.join(tmp_dir, "ms.pdf")
        pdf = pikepdf.new()
        page = pdf.add_blank_page(page_size=(400, 400))
        w = pdf.make_indirect(
            Dictionary(
                Type=Name.Annot, Subtype=Name.Widget, Rect=[40, 300, 200, 380],
                FT=Name("/Ch"), T=pikepdf.String("colors"), Ff=FF_MULTISELECT,
                Opt=pikepdf.Array([
                    pikepdf.Array([pikepdf.String("r"), pikepdf.String("Red")]),
                    pikepdf.Array([pikepdf.String("g"), pikepdf.String("Green")]),
                    pikepdf.Array([pikepdf.String("b"), pikepdf.String("Blue")]),
                ]),
                P=page.obj,
            )
        )
        page.obj["/Annots"] = pikepdf.Array([w])
        pdf.Root["/AcroForm"] = Dictionary(
            Fields=pikepdf.Array([w]), DA=pikepdf.String("/Helv 10 Tf 0 g")
        )
        pdf.save(src)
        pdf.close()
        out = os.path.join(tmp_dir, "mso.pdf")
        assert fill_form_fields(src, out, {"colors": ["Red", "Blue"]})["filled"] == 1
        with pikepdf.open(out) as p:
            f = p.Root["/AcroForm"]["/Fields"][0]
            assert [str(x) for x in f["/V"]] == ["r", "b"]  # exports
            assert [int(x) for x in f["/I"]] == [0, 2]  # sorted /Opt indices
            assert "/AP" in f  # appearance regenerated
        assert read_form_fields(out)["fields"][0]["value"] == ["r", "b"]
        # A single string still selects one item (backward compatible).
        out2 = os.path.join(tmp_dir, "mso2.pdf")
        fill_form_fields(src, out2, {"colors": "Green"})
        with pikepdf.open(out2) as p:
            assert str(p.Root["/AcroForm"]["/Fields"][0]["/V"]) == "g"

    def test_fc4_multiselect_rejects_bad_option(self, tmp_dir):
        # An element that is not an option is refused (atomically), listing it.
        src = os.path.join(tmp_dir, "ms2.pdf")
        pdf = pikepdf.new()
        page = pdf.add_blank_page(page_size=(400, 400))
        w = pdf.make_indirect(
            Dictionary(
                Type=Name.Annot, Subtype=Name.Widget, Rect=[40, 300, 200, 380],
                FT=Name("/Ch"), T=pikepdf.String("colors"), Ff=FF_MULTISELECT,
                Opt=pikepdf.Array([pikepdf.String("Red"), pikepdf.String("Blue")]),
                P=page.obj,
            )
        )
        page.obj["/Annots"] = pikepdf.Array([w])
        pdf.Root["/AcroForm"] = Dictionary(Fields=pikepdf.Array([w]), DA=pikepdf.String("/Helv 10 Tf 0 g"))
        pdf.save(src)
        pdf.close()
        out = os.path.join(tmp_dir, "ms2o.pdf")
        with pytest.raises(ValueError, match="no option"):
            fill_form_fields(src, out, {"colors": ["Red", "Purple"]})
        assert not os.path.exists(out)

    def test_fc4_multiselect_promotes_ff_flag(self, tmp_dir):
        # regression: writing 2+ selections onto a NON-multiselect list box
        # sets the /Ff MultiSelect bit (else the array /V is spec-non-conformant,
        # which pdf-lib never produces — it auto-promotes).
        src = os.path.join(tmp_dir, "nf.pdf")
        pdf = pikepdf.new()
        page = pdf.add_blank_page(page_size=(400, 400))
        w = pdf.make_indirect(
            Dictionary(
                Type=Name.Annot, Subtype=Name.Widget, Rect=[40, 300, 200, 380],
                FT=Name("/Ch"), T=pikepdf.String("c"), Ff=0,  # NOT multiselect
                Opt=pikepdf.Array([pikepdf.String("Red"), pikepdf.String("Green"), pikepdf.String("Blue")]),
                P=page.obj,
            )
        )
        page.obj["/Annots"] = pikepdf.Array([w])
        pdf.Root["/AcroForm"] = Dictionary(Fields=pikepdf.Array([w]), DA=pikepdf.String("/Helv 10 Tf 0 g"))
        pdf.save(src)
        pdf.close()
        out = os.path.join(tmp_dir, "nfo.pdf")
        fill_form_fields(src, out, {"c": ["Red", "Blue"]})
        with pikepdf.open(out) as p:
            assert int(p.Root["/AcroForm"]["/Fields"][0].get("/Ff", 0)) & FF_MULTISELECT

    def test_fc4_empty_value_clears_choice_selection(self, tmp_dir):
        # regression follow-on: an EMPTY value CLEARS a choice selection
        # (pdf-lib's field.clear()) instead of erroring "no option ''". A GUI
        # that lets the user deselect a radio/dropdown depends on this.
        out1 = os.path.join(tmp_dir, "c1.pdf")
        fill_form_fields(PDFLIB_FORM, out1, {"color": "blue", "size": "medium"})
        b1 = {f["name"]: f["value"] for f in read_form_fields(out1)["fields"]}
        assert b1["color"] == "blue" and b1["size"] == "medium"
        out2 = os.path.join(tmp_dir, "c2.pdf")
        fill_form_fields(out1, out2, {"color": "", "size": ""})  # deselect both
        b2 = {f["name"]: f["value"] for f in read_form_fields(out2)["fields"]}
        assert b2["color"] == ""  # radio de-selected → /Off
        assert b2["size"] == ""  # dropdown de-selected → /V dropped

    def test_fc3_widget_in_two_pages_annots_not_misattributed(self, tmp_dir):
        # regression: the SAME widget object listed in TWO pages' /Annots
        # (malformed third-party input) must NOT be silently pinned to one page.
        # With no /P it reports page None (unplaced) — the scan never guesses.
        out = os.path.join(tmp_dir, "dup.pdf")
        pdf = pikepdf.new()
        p0 = pdf.add_blank_page(page_size=(300, 300))
        p1 = pdf.add_blank_page(page_size=(300, 300))
        w = pdf.make_indirect(
            Dictionary(
                Type=Name.Annot, Subtype=Name.Widget, Rect=[1, 2, 3, 4],
                FT=Name.Tx, T=pikepdf.String("dup"),
            )
        )
        p0.obj["/Annots"] = pikepdf.Array([w])
        p1.obj["/Annots"] = pikepdf.Array([w])
        pdf.Root["/AcroForm"] = Dictionary(Fields=pikepdf.Array([w]))
        pdf.save(out)
        pdf.close()
        dup = next(f for f in read_form_fields(out)["fields"] if f["name"] == "dup")
        assert dup["widgets"] == [{"page": None, "rect": [1.0, 2.0, 3.0, 4.0], "hidden": False}]

    def test_fc3_ambiguous_widget_resolves_via_P(self, tmp_dir):
        # The ambiguous (two-/Annots) widget's spec-authoritative /P disambiguates
        # to page 1 rather than falling to None.
        out = os.path.join(tmp_dir, "dupP.pdf")
        pdf = pikepdf.new()
        p0 = pdf.add_blank_page(page_size=(300, 300))
        p1 = pdf.add_blank_page(page_size=(300, 300))
        w = pdf.make_indirect(
            Dictionary(
                Type=Name.Annot, Subtype=Name.Widget, Rect=[1, 2, 3, 4],
                FT=Name.Tx, T=pikepdf.String("dup"), P=p1.obj,
            )
        )
        p0.obj["/Annots"] = pikepdf.Array([w])
        p1.obj["/Annots"] = pikepdf.Array([w])
        pdf.Root["/AcroForm"] = Dictionary(Fields=pikepdf.Array([w]))
        pdf.save(out)
        pdf.close()
        dup = next(f for f in read_form_fields(out)["fields"] if f["name"] == "dup")
        assert dup["widgets"] == [{"page": 1, "rect": [1.0, 2.0, 3.0, 4.0], "hidden": False}]

